import gradio as gr
import pandas as pd
import plotly.express as px
import plotly.graph_objects as go
from datasets import load_dataset

_ARCH_B64 = ""

HF_DATASET = "abhinavp10/llm-benchmark-results"
MODELS = ["LLaMA-3.2-3B", "Falcon-7B", "Mistral-7B"]
MODEL_COLORS = {"LLaMA-3.2-3B": "#4F8EF7", "Falcon-7B": "#F7634F", "Mistral-7B": "#4FD18A"}

PLOT_LAYOUT = dict(
    plot_bgcolor="#0d1117", paper_bgcolor="#161b22",
    font_color="#c9d1d9", font_family="Segoe UI, sans-serif",
    legend=dict(bgcolor="#21262d", bordercolor="#30363d", borderwidth=1),
    xaxis=dict(gridcolor="#21262d", linecolor="#30363d"),
    yaxis=dict(gridcolor="#21262d", linecolor="#30363d"),
    margin=dict(t=48, b=32, l=32, r=32)
)


def load_results() -> pd.DataFrame:
    try:
        ds = load_dataset(HF_DATASET, split="train")
        return ds.to_pandas()
    except Exception:
        return pd.DataFrame()


def make_empty_fig(message: str):
    fig = go.Figure()
    fig.add_annotation(text=message, xref="paper", yref="paper",
                       x=0.5, y=0.5, showarrow=False,
                       font=dict(size=15, color="#8b949e"))
    fig.update_layout(height=320, **PLOT_LAYOUT)
    return fig


def get_summary_table(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return pd.DataFrame({"Status": ["No results yet — run the Colab notebook first"]})
    rows = []
    for model in MODELS:
        mdf = df[df["model"] == model]
        if mdf.empty:
            continue
        row = {"Model": model}
        summ = mdf[mdf["task"] == "summarization"]
        row["ROUGE-1"] = round(summ["rouge1"].mean(), 4) if not summ.empty and "rouge1" in summ else "—"
        row["ROUGE-L"] = round(summ["rougeL"].mean(), 4) if not summ.empty and "rougeL" in summ else "—"
        trans = mdf[mdf["task"] == "translation"]
        row["BLEU"] = round(trans["bleu"].mean(), 2) if not trans.empty and "bleu" in trans else "—"
        reas = mdf[mdf["task"] == "reasoning"]
        row["Accuracy"] = round(reas["accuracy"].mean(), 2) if not reas.empty and "accuracy" in reas else "—"
        row["Avg Latency (s)"] = round(mdf["latency_s"].mean(), 3) if "latency_s" in mdf else "—"
        row["Avg Memory (MB)"] = round(mdf["memory_mb"].mean(), 1) if "memory_mb" in mdf else "—"
        row["Tokens/sec"] = round(mdf["tokens_per_sec"].mean(), 2) if "tokens_per_sec" in mdf else "—"
        rows.append(row)
    return pd.DataFrame(rows)


def plot_quality_metrics(df: pd.DataFrame):
    if df.empty:
        return make_empty_fig("No data — run the Colab notebook to generate results")
    fig = go.Figure()
    summ = df[df["task"] == "summarization"].groupby("model")["rougeL"].mean().reset_index()
    for _, r in summ.iterrows():
        fig.add_trace(go.Bar(name=r["model"], x=["Summarization (ROUGE-L)"], y=[r["rougeL"]],
                             marker_color=MODEL_COLORS.get(r["model"], "#888"),
                             legendgroup=r["model"], showlegend=True))
    trans = df[df["task"] == "translation"].groupby("model")["bleu"].mean().reset_index()
    for _, r in trans.iterrows():
        fig.add_trace(go.Bar(name=r["model"], x=["Translation (BLEU/100)"], y=[r["bleu"] / 100],
                             marker_color=MODEL_COLORS.get(r["model"], "#888"),
                             legendgroup=r["model"], showlegend=False))
    reas = df[df["task"] == "reasoning"].groupby("model")["accuracy"].mean().reset_index()
    for _, r in reas.iterrows():
        fig.add_trace(go.Bar(name=r["model"], x=["Reasoning (Accuracy)"], y=[r["accuracy"]],
                             marker_color=MODEL_COLORS.get(r["model"], "#888"),
                             legendgroup=r["model"], showlegend=False))
    fig.update_layout(title="Quality Scores by Task  (higher = better)", barmode="group",
                      yaxis=dict(title="Score (0 – 1)", range=[0, 1]), height=400, **PLOT_LAYOUT)
    return fig


def plot_rouge_breakdown(df: pd.DataFrame):
    if df.empty:
        return make_empty_fig("No data — run the Colab notebook to generate results")
    summ = df[df["task"] == "summarization"].groupby("model")[["rouge1", "rouge2", "rougeL"]].mean().reset_index()
    melted = summ.melt(id_vars="model", var_name="Metric", value_name="Score")
    fig = px.bar(melted, x="model", y="Score", color="Metric", barmode="group",
                 title="ROUGE Score Breakdown — Summarization Task",
                 color_discrete_map={"rouge1": "#4F8EF7", "rouge2": "#F7634F", "rougeL": "#4FD18A"},
                 labels={"model": "Model"})
    fig.update_layout(height=380, **PLOT_LAYOUT)
    return fig


def plot_latency(df: pd.DataFrame):
    if df.empty:
        return make_empty_fig("No data — run the Colab notebook to generate results")
    lat = df.groupby(["model", "task"])["latency_s"].mean().reset_index()
    fig = px.bar(lat, x="task", y="latency_s", color="model", barmode="group",
                 title="Average Inference Latency by Task  (lower = better)",
                 color_discrete_map=MODEL_COLORS, labels={"task": "Task", "latency_s": "Latency (s)", "model": "Model"})
    fig.update_layout(height=380, **PLOT_LAYOUT)
    return fig


def plot_memory(df: pd.DataFrame):
    if df.empty:
        return make_empty_fig("No data — run the Colab notebook to generate results")
    mem = df.groupby("model")["memory_mb"].mean().reset_index()
    fig = px.bar(mem, x="model", y="memory_mb", color="model",
                 title="Average GPU Memory Usage per Model  (lower = better)",
                 color_discrete_map=MODEL_COLORS, labels={"model": "Model", "memory_mb": "Memory (MB)"})
    fig.update_layout(showlegend=False, height=360, **PLOT_LAYOUT)
    return fig


def plot_tps(df: pd.DataFrame):
    if df.empty:
        return make_empty_fig("No data — run the Colab notebook to generate results")
    tps = df.groupby("model")["tokens_per_sec"].mean().reset_index()
    fig = px.bar(tps, x="model", y="tokens_per_sec", color="model",
                 title="Average Tokens per Second  (higher = better)",
                 color_discrete_map=MODEL_COLORS, labels={"model": "Model", "tokens_per_sec": "Tokens/sec"})
    fig.update_layout(showlegend=False, height=360, **PLOT_LAYOUT)
    return fig


def refresh_all():
    df = load_results()
    return (
        get_summary_table(df),
        plot_quality_metrics(df),
        plot_rouge_breakdown(df),
        plot_latency(df),
        plot_memory(df),
        plot_tps(df),
    )


